import React, { useState, useEffect } from 'react';
import 'react-datepicker/dist/react-datepicker.css';
import '../styles/List.css';
import ReservationForm from './ReservationForm';

const formatUTCDate = () => {
  const date = new Date();
  const day = String(date.getUTCDate()).padStart(2, '0');
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const year = date.getUTCFullYear();
  const hours = String(date.getUTCHours()).padStart(2, '0');
  const minutes = String(date.getUTCMinutes()).padStart(2, '0');
  return `${day}-${month}-${year} ${hours}:${minutes}z`;
};

const formatUTCTime = () => {
  const date = new Date();
  const hours = String(date.getUTCHours()).padStart(2, '0');
  const minutes = String(date.getUTCMinutes()).padStart(2, '0');
  return `${hours}:${minutes}z`;
};

const TopMenu = ({ user, view, onPageSelect }) => {
  const [filter, setFilter] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [utcTime, setUtcTime] = useState(formatUTCDate());
  const [activePage, setActivePage] = useState('Reservations');
  const [isSmallScreen, setIsSmallScreen] = useState(false);

  const openModal = () => setIsModalOpen(true);
  const closeModal = () => setIsModalOpen(false);

  useEffect(() => {
    setUtcTime(formatUTCDate());

    const interval = setInterval(() => {
      setUtcTime(formatUTCDate());
    }, 60000); // Update every minute

    const handleResize = () => {
      setIsSmallScreen(window.innerWidth < 900);
    };

    window.addEventListener('resize', handleResize);
    handleResize(); // Initial check

    return () => {
      clearInterval(interval);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  const handlePageSelect = (page) => {
    setActivePage(page);
    onPageSelect(page);
  };

  return (
    <div>
      {/* Top Menu */}
      <div className="top-menu">
        <div style={{ paddingLeft: '4px' }}>
          {/* Add your logo or other content here */}
        </div>

        <span className='time-container'>
          <img src='images/time.svg' alt='Time'></img>
          <span>{isSmallScreen ? formatUTCTime() : utcTime}</span>
        </span>

        <div>
          <button className="add-button" onClick={openModal}>
            {isSmallScreen ? '+' : 'Add reservation'}
          </button>
        </div>
      </div>

      <div style={{backgroundColor: '#fff'}}>
        <span
          className={`page-selection ${activePage === 'Reservations' ? 'active-page-title' : ''}`}
          onClick={() => handlePageSelect('Reservations')}
        >
          Reservations
        </span>
        <span
          className={`page-selection ${activePage === 'Chart' ? 'active-page-title' : ''}`}
          onClick={() => handlePageSelect('Chart')}
        >
          Chart
        </span>
      </div>

      {/* Modal */}
      {isModalOpen && (
        <ReservationForm
          user={user}
          view={view}
          isOpen={isModalOpen}
          onClose={closeModal}
          mode="create"
          onCreate={(reservation) => {
            closeModal();
          }}
        />
      )}
    </div>
  );
};

export default TopMenu;
