import React, { useState, useEffect } from 'react';
import { LOGIN_URL, PROFILE_URL } from '../config';
import styled from 'styled-components';
import Alert from 'react-bootstrap/Alert';
import { MenuItem, Select, FormControl, InputLabel } from '@mui/material';
import { useLocation } from './AreaContext';

const LoginPage = styled.div`
  display: flex;
  height: 100vh;
  background-color: black;
  -webkit-user-select: none;
  -ms-user-select: none;
  user-select: none;

  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const ContentSection = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 30px;
  background-color: #011328;
  color: white;
  z-index: 1;

  @media (max-width: 768px) {
    width: 100%;
  }
`;

const Title = styled.h1`
  font-size: 2.2rem;
  margin-top: 20px;
  margin-bottom: 20px;
  text-align: center;
  color: #dfebeb;
`;

const LoginButton = styled.button`
  background-color: #176498;
  color: white;
  padding: 6px;
  border: none;
  font-size: 12pt;
  cursor: pointer;
  width: 100%;
  height: 40px;

  &:hover {
    background-color: #0056b3;
  }

  @media (max-width: 768px) {
    width: 100%;
    font-size: 1rem;
  }
`;

const Logo = styled.img`
  margin-top: 20px;
  margin-right: 20px;
  width: auto;
  height: 60px;
  display: inline;
`;

const LoadingContainer = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background-color: black;
  color: white;
`;

const LoadingText = styled.p`
  font-size: 1.0rem;
  margin-bottom: 20px;
`;

const LoadingGif = styled.img`
  width: 16px;
  height: 16px;
  margin-left: 10px;
`;

const ImageSection = styled.div`
  position: relative;
  flex: 1;
  background: ${({ bgImage }) => `url(${bgImage})`};
  background-repeat: no-repeat;
  background-position: left top;
  background-size: cover;
  height: 100%;
  opacity: 0.7;

  @media (max-width: 768px) {
    display: none;
  }
`;

const ColorExplanation = styled.div`
  position: absolute;
  bottom: 0;
  left: 0;
  padding: 10px 20px;
  color: white;
  font-size: 0.9rem;
  width: 100%;
  display: flex;
  justify-content: center;
  gap: 20px;

  @media (max-width: 768px) {
    display: none;
  }
`;

const Login = () => {
  const [loginError, setLoginError] = useState(null);
  const [loading, setLoading] = useState(true);
  const { selectedLocation, setSelectedLocation } = useLocation();
  const [bgIndex, setBgIndex] = useState(0);

  const backgroundImages = ['images/login-background.png', 'images/login-background2.png'];

  /*
  useEffect(() => {
    const interval = setInterval(() => {
      setBgIndex((prevIndex) => (prevIndex + 1) % backgroundImages.length);
    }, 10000); // rotate every 10 seconds

    return () => clearInterval(interval);
  }, []);
  */

  useEffect(() => {
    const checkAuthentication = async () => {
      try {
        const response = await fetch(PROFILE_URL, {
          credentials: 'include',
        });

        if (response.ok) {
          setLoginError('')
          window.location.href = '/';
        } else {
          setLoading(false);
          setLoginError('')
        }
      } catch (error) {
        console.error('Error checking authentication:', error);
        setLoading(false);
        setLoginError('Login Failed. If problems persist, please contact your system administrator.')
      }
    };

    checkAuthentication();
  }, []);

  const handleLogin = () => {
    if (selectedLocation) {
      window.location.href = LOGIN_URL;
    } else {
      setLoginError('Please select area first.');
    }
  };  

  if (loading) {
    return (
      <LoadingContainer>
        <LoadingText>
          Loading
          <LoadingGif src="images/ajax-loader.gif" alt="Loading" />
        </LoadingText>
      </LoadingContainer>
    );
  }

  return (
    <LoginPage>
      <ImageSection bgImage={backgroundImages[bgIndex]}>
        {backgroundImages[bgIndex] === 'images/login-background.png' && (
          <ColorExplanation>
            <p style={{ background: '#8c5473', padding: '0 4px' }}>Under consideration</p> 
            <p style={{ background: '#c17c02', padding: '0 4px' }}>Pre-operational</p> 
            <p style={{ background: '#2c6809', padding: '0 4px' }}>Operational</p> 
          </ColorExplanation>
        )}
      </ImageSection>
      <ContentSection>
        <div style={{ display: 'inline', alignItems: 'center'}}>
          <Logo src="images/logo.svg" alt="VATSIM Scandinavia" />
          <Logo src='images/vlara-logo.svg' alt='V-LARA' style={{height: '36px', marginLeft: '10px'}}/>
        </div>

        <Title>LARA Web Booking Client</Title>

        <div style={{ display: 'flex', alignItems: 'center', width: '100%', marginBottom: '20px' }}>
          <FormControl style={{ marginRight: '10px', flex: 1 }}>
            <Select
              className='text-fields no-border-radius'
              id="area-select"
              value={selectedLocation}
              onChange={(e) => setSelectedLocation(e.target.value)}
              size="small"
            >
              <MenuItem value="efin" className='login-finland'>EFINZAMC | Finland</MenuItem>
              
              <MenuItem value="eett" style={{color: '#a1a1a1'}}>EETTZAMC | Estonia (not operational)</MenuItem>
              <MenuItem value="eacc" style={{color: '#a1a1a1'}}>EACCZAMC | Amswell (test environment)</MenuItem>
            </Select>
          </FormControl>
          <LoginButton onClick={handleLogin} style={{ flex: 1 }}>Login with VATSIM</LoginButton>
        </div>


        {loginError && <p style={{ color: 'red' }}>{loginError}</p>}

        <Alert key={'success'} variant={'success'} style={{width: '100%', borderRadius: '0'}}>
          <b>Local and sub-regional airspace management support system</b><br/>
          Create and manage airspace reservations on VATSIM network!
        </Alert>

        <div>
          <a href='https://wiki.vatsim-scandinavia.org/books/finnish-airports-charts/page/v-lara-airspace-reservation' target='_blank' rel='noopener noreferrer' style={{paddingRight: '20px'}}>
            <img src='images/manual.svg' alt='manual' style={{paddingRight: '6px'}}></img>
            Pilot manual
          </a>

          <a href='https://wiki.vatsim-scandinavia.org/books/special-procedures/page/v-lara-atc-guide' target='_blank' rel='noopener noreferrer'>
            <img src='images/manual.svg' alt='manual' style={{paddingRight: '6px'}}></img>
            ATC manual
          </a>
        </div>

      </ContentSection>
    </LoginPage>
  );
};

export default Login;

