import '../styles/List.css';
import '../styles/Notif.css';
import React, { useState, useEffect } from 'react';
import { LOGOUT_URL } from '../config';
import Tooltip from '@mui/material/Tooltip';
import { useLocation } from './AreaContext';

const LeftMenu  = ({ view }) => {
    const [showLogoutModal, setShowLogoutModal] = useState(false);
    const [showAboutModal, setShowAboutModal] = useState(false);
    const [showWarningModal, setShowWarningModal] = useState(false);
    const { selectedLocation } = useLocation(); 
    const [notificationsViewed, setNotificationsViewed] = useState(false);
    const [notifications, setNotifications] = useState([
        // Example notification
        { 
            id: 1,
            timestamp: '16 JUL 2025',
            title: 'New Version Release', 
            message: 'V-LARA now supports adding multiple FIRs. The booking functionality can be tested using the EACCZAMC profile.', 
             
        },
    ]);

    const openAboutModal = () => setShowAboutModal(true);
    const openLogoutModal = () => setShowLogoutModal(true);
    const closeLogoutModal = () => setShowLogoutModal(false);
    const closeWarningModal = () => setShowWarningModal(false);
    const closeAboutModal = () => setShowAboutModal(false);

    const openWarningModal = () => {
        const latestTimestamp = Math.max(...notifications.map(n => new Date(n.timestamp).getTime()));
        localStorage.setItem('notificationsViewed', 'true');
        localStorage.setItem('lastSeenNotificationTimestamp', String(latestTimestamp));
        setNotificationsViewed(true);
        setShowWarningModal(true);
    };

    useEffect(() => {
        const viewed = localStorage.getItem('notificationsViewed') === 'true';
        setNotificationsViewed(viewed);
    }, []);

    useEffect(() => {
        const storedViewed = localStorage.getItem('notificationsViewed') === 'true';
        const lastSeen = parseInt(localStorage.getItem('lastSeenNotificationTimestamp') || '0', 10);
    
        if (notifications.length > 0 && storedViewed) {
            const maxTimestamp = Math.max(...notifications.map(n => new Date(n.timestamp).getTime()));
    
            if (maxTimestamp > lastSeen) {
                localStorage.setItem('notificationsViewed', 'false');
                setNotificationsViewed(false);
            }
        }
    }, [notifications]);

    const handleLogout = async () => {
        try {
            const response = await fetch(LOGOUT_URL, {
                method: 'POST',
                credentials: 'include',
            });

            if (response.ok) {
                window.location.href = '/';
            } else {
                console.error('Logout failed:', await response.json());
            }
        } catch (error) {
            console.error('Error during logout:', error);
        }
    };

    const styles = {
        container: {
            height: '100%',
            width: '60px',
            position: 'fixed',
            left: '0',
            top: '0',
            backgroundColor: '#1a475f',
            zIndex: 10,
        },
        modal: {
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            zIndex: 1000,
            backgroundColor: '0px 0px 15px rgba(0,0,0,0.5)',
            padding: '20px',
        },
        modalContent: {
            textAlign: 'center',
        },
        modalButton: {
            margin: '6px',
            padding: '10px',
            border: 'none',
            cursor: 'pointer',
            borderRadius: '0px',
        },
    };

    const handleHelpClick = () => {
        const url = view === 'ATCView'
            ? 'https://wiki.vatsim-scandinavia.org/books/special-procedures/page/v-lara-atc-guide'
            : 'https://wiki.vatsim-scandinavia.org/books/finnish-airports-charts/page/v-lara-airspace-reservation';
        window.open(url, '_blank');
    };

    return (
        <div style={styles.container}>
            <img src='images/vlara-logo.svg' style={{width: '30px', margin: '15px', marginBottom: '10px', cursor: 'pointer'}} onClick={() => window.open('https://vatsim-scandinavia.org/', '_blank')}></img>
            <p className="amc-text-2" style={selectedLocation === 'eacc' ? { color: 'red' } : undefined}>
                {selectedLocation?.toUpperCase()}
            </p>
            <p className='amc-text'>
                {view === 'ATCView' ? 'AMC' : ''}
            </p>
            <div className="button-stack">
                <Tooltip placement="right" title="Notifications" arrow>
                    <button className="icon-button warning-button" onClick={openWarningModal} 
                        style={{ position: 'relative', backgroundColor: notifications.length === 0 ? '#1a475f' : '#db8300'}
                    }>
                        <img src="images/warning.svg" alt="Alert" />
                        {notifications.length > 0 && !notificationsViewed && (
                            <span className="notification-count">
                                {notifications.length}
                            </span>
                        )}
                    </button>
                </Tooltip>

                <Tooltip placement="right" title="Web Services Connection Status" arrow>
                    <button className="icon-button status-button" style={{ cursor: 'auto' }}>
                    <img src="images/check.svg" alt="Status" />
                    </button>
                </Tooltip>

                <Tooltip placement="right" title="User Guide" arrow>
                    <button className="icon-button info-button" onClick={handleHelpClick}>
                    <img src="images/help.svg" alt="Help" />
                    </button>
                </Tooltip>

                <Tooltip placement="right" title="About" arrow>
                    <button className="icon-button about-button" onClick={openAboutModal}>
                    <img src="images/info.svg" alt="Help" />
                    </button>
                </Tooltip>

                <Tooltip placement="right" title="Logout from WBC" arrow>
                    <button className="icon-button logout-button" onClick={openLogoutModal}>
                    <img src="images/logout.svg" alt="Logout" />
                    </button>
                </Tooltip>
            </div>

            {/* Logout Confirmation Modal */}
            {showLogoutModal && (
                <div className="logout-modal" style={styles.modal}>
                    <div className="logout-modal-content" style={styles.modalContent}>
                        <h3>Confirm Logout</h3>
                        <p>Are you sure you want to log out?</p>
                        <button onClick={handleLogout} style={{ ...styles.modalButton, backgroundColor: 'rgb(203, 28, 28)' }}>
                            Logout
                        </button>
                        <button onClick={closeLogoutModal} style={{ ...styles.modalButton, backgroundColor: '#0f8dcc' }}>
                            Cancel
                        </button>
                    </div>
                </div>
            )}

            {showWarningModal && (
                <>
                    <div className="notification-modal-overlay" onClick={closeWarningModal} />
                    <div className="notification-modal">
                        <h3>Notifications</h3>
                        {notifications.length === 0 ? (
                            <p style={{ textAlign: 'center' }}>NIL</p>
                        ) : (
                            notifications.map((notif) => (
                                <div key={notif.id} className="warning-item">
                                    <div className="timestamp">
                                    <span className="notif-id">{notif.id}</span>
                                    {notif.timestamp}
                                    </div>
                                    <div className="alert-modal-text" style={{fontWeight: 'bold'}}>{notif.title}</div>
                                    <div className="alert-modal-text">{notif.message}</div>
                                </div>
                            ))
                        )}
                        <button className="modal-button" onClick={closeWarningModal}>Close</button>
                    </div>
                </>
            )}

            {showAboutModal && (
                <>
                    <div className="notification-modal-overlay" onClick={closeAboutModal} />
                    <div className="notification-modal" style={{width: '700px'}}>
                        <div className='about-modal'>
                            <img src='images/vlara-logo.svg'></img>
                            <h4>About V-LARA</h4>
                        </div>
                        <div className='about-modal-content'>
                            <p>Lara Version</p>
                            <p>1.0.2</p>
                        </div>
                        <div className='about-modal-content'>
                            <p>Release Date</p>
                            <p>16/07/2025</p>
                        </div>
                        <div className='about-modal-content'>
                            <p>Data Repository</p>
                            <p><a href='https://github.com/ottotuhkunen/virtual-lara-airspace-data/tree/main' target="_blank" rel="noopener noreferrer">Dev files</a></p>
                        </div>

                        <div className='about-modal-content'>
                            <p>Selected Location</p>
                            <p>{selectedLocation.toUpperCase()}</p>
                        </div>
                        <div className='about-modal-content'>
                            <p>User Role</p>
                            <p>{view === 'ATCView' ? 'AMC' : 'DEFAULT'}</p>
                        </div>

                        <p style={{marginTop: '20px'}}>
                            V-LARA is a web-based simulation tool inspired by the real-life counterpart developed by Eurocontrol for airspace reservation and coordination. V-LARA offers VATSIM controllers, pilots and vSO organizations an interactive experience that combines elements of both the LARA Web Booking Client (WBC) and the Airspace Management Cell (AMC) Working Position in one application.
                        </p>

                        <p>
                            This tool connects seamlessly with the TopSky plugin giving controllers a more realistic experience with automated PREACTIVE areas, area activation process and coordination. Online ATCOs are responsible for handling the reservations under their AoR, as we do not have 24/7 AMC and NM roles on VATSIM.
                        </p>

                        <button className="modal-button" style={{marginTop: '20px'}} onClick={closeAboutModal}>Close</button>
                    </div>
                </>
            )}


            
        </div>
    );
};

export default LeftMenu;
